(() => {
'use strict';
const screens=window.premiereScreens;
const order=['Video','Audio','Browse','Playlists','Playback','More & settings','First run','Remote pairing','Dialogs'];
const art=['golden-hour','alpine','coast','night-sky','desert','forest'];
const films=['The Long Way Home','Above the Clouds','Blue Between','A Quiet Universe','Where the Road Ends','The Green Distance'];
const durations=['1:42:18','48:06','1:16:42','52:31','1:33:09','39:12'];
const tracks=['First Light','Open Road','Almost Home','A Little Further','The Quiet Hours','Last Light'];
const trackTimes=['3:40','4:41','4:02','3:43','4:44','5:10'];
const icons={play:'<path d="m8 5 12 7-12 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',back:'<path d="m14 5-7 7 7 7"/>',next:'<path d="m10 5 7 7-7 7"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',more:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',video:'<rect x="3" y="5" width="18" height="14" rx="2"/><path d="m10 9 5 3-5 3Z"/>',audio:'<path d="M9 17V5l11-2v12M9 8l11-2"/><ellipse cx="6" cy="18" rx="3" ry="2"/><ellipse cx="17" cy="16" rx="3" ry="2"/>',folder:'<path d="M3 7h7l2 2h9v11H3Z"/>',list:'<path d="M7 6h14M7 12h14M7 18h14M3 6h.1M3 12h.1M3 18h.1"/>',settings:'<circle cx="12" cy="12" r="4"/><path d="M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2"/>',check:'<path d="m4 12 5 5L20 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',plus:'<path d="M12 4v16M4 12h16"/>',cast:'<path d="M3 8V4h18v14H11M3 14a4 4 0 0 1 4 4M3 10a8 8 0 0 1 8 8"/><circle cx="3" cy="18" r="1"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V6a4 4 0 0 1 8 0v4"/>',shuffle:'<path d="M3 5c8 0 10 14 18 14M3 19c8 0 10-14 18-14M17 2l4 3-4 3M17 16l4 3-4 3"/>',volume:'<path d="M3 9h4l5-5v16l-5-5H3Z"/><path d="M16 7a7 7 0 0 1 0 10M19 4a11 11 0 0 1 0 16"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3M12 20v3M1 12h3M20 12h3M4 4l2 2M18 18l2 2M4 20l2-2M18 6l2-2"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',headphones:'<path d="M4 14V10a8 8 0 0 1 16 0v4"/><rect x="3" y="12" width="4" height="9" rx="2"/><rect x="17" y="12" width="4" height="9" rx="2"/>',network:'<rect x="8" y="2" width="8" height="6" rx="1"/><path d="M12 8v5M4 17v-4h16v4"/><rect x="1" y="17" width="6" height="5"/><rect x="17" y="17" width="6" height="5"/>',bookmark:'<path d="M6 3h12v18l-6-4-6 4Z"/>',drag:'<path d="M8 5h.1M16 5h.1M8 12h.1M16 12h.1M8 19h.1M16 19h.1"/>'};
const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const ico=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.next}</svg>`;
const btn=(text,target,cls='button',action)=>`<button class="${cls}" ${target?`data-target="${target}"`:`data-action="${esc(action||text)}"`}>${text}</button>`;
const ib=(name,label,target,action)=>`<button class="icon-button" aria-label="${esc(label)}" ${target?`data-target="${target}"`:`data-action="${esc(action||label)}"`}>${ico(name)}</button>`;
const img=(i,cls='',alt='')=>`<img class="${cls}" src="../assets/${art[i%6]}.jpg" alt="${esc(alt||films[i%6])}" loading="lazy">`;
const row=(title,sub='',target,icon='next',options={})=>`<button class="row ${options.active?'selected':''}" ${target?`data-target="${target}"`:`data-action="${esc(title)}"`}><span class="row-icon">${options.image!==undefined?img(options.image,'',title):ico(icon)}</span><span class="row-copy"><strong>${esc(title)}</strong>${sub?`<small>${esc(sub)}</small>`:''}</span><span class="row-end">${options.end?esc(options.end):ico('next')}</span></button>`;
const toggle=(title,sub='',on=true)=>`<button class="setting-row" role="switch" aria-checked="${on}" data-toggle><span><strong>${esc(title)}</strong>${sub?`<small>${esc(sub)}</small>`:''}</span><span class="switch" aria-hidden="true"></span></button>`;
const setting=(title,value,target)=>`<button class="setting-row" ${target?`data-target="${target}"`:`data-action="${esc(title)}"`}><span><strong>${esc(title)}</strong><small>${esc(value)}</small></span>${ico('next')}</button>`;
const group=(title,html)=>`<p class="section-label">${title}</p><div class="settings-group">${html}</div>`;
const field=(label,value='',type='text',placeholder='')=>`<label class="form-field"><span>${label}</span><input type="${type}" value="${esc(value)}" placeholder="${esc(placeholder)}" aria-label="${esc(label)}"></label>`;
const choice=(title,sub,checked=false)=>`<button class="radio-row" data-choice aria-pressed="${checked}"><span class="radio" aria-hidden="true"></span><span><strong>${title}</strong>${sub?`<small>${sub}</small>`:''}</span></button>`;
const chips=(values,selected)=>`<div class="chips">${values.map(v=>`<button data-choice class="chip" aria-pressed="${v===selected}">${v}</button>`).join('')}</div>`;
const range=(label,value,min=0,max=100,step=1)=>`<label class="range-field"><span>${label}<output>${value}</output></span><input type="range" aria-label="${label}" min="${min}" max="${max}" step="${step}" value="${value}"></label>`;
const nav=(active)=>`<nav class="bottom-nav" aria-label="App navigation">${[['Video','video','video-library'],['Audio','audio','audio-artists'],['Browse','folder','browse'],['Playlists','list','playlists'],['More','more','more']].map(([t,i,d])=>`<button data-target="${d}" ${active===t?'aria-current="page"':''}>${ico(i)}<span>${t}</span></button>`).join('')}</nav>`;
const tabsAudio=(active)=>`<div class="audio-tabs">${[['Artists','audio-artists'],['Albums','audio-albums'],['Tracks','audio-tracks'],['Genres','audio-genres']].map(([a,id])=>btn(a,id,active===a?'active':'')).join('')}</div>`;
const heading=(title,subtitle='',right='',back)=>`<div class="app-heading">${back?ib('back','Back',back):'<span class="vlc-mark">▲</span>'}<span>${back?'VLC': 'VLC <small>PREMIERE</small>'}</span><div>${right||ib('search','Search media','search')+ib('more','Display options','display-options')}</div></div><h3 class="page-title">${title}</h3>${subtitle?`<p class="page-subtitle">${subtitle}</p>`:''}`;
const coverGrid=(names=films,target='media-details')=>`<div class="cover-grid">${names.map((n,i)=>`<button class="cover" data-target="${target}">${img(i,'',n)}<strong>${n}</strong><small>${films.includes(n)?durations[films.indexOf(n)]:'Mara Ellison · 2024'}</small></button>`).join('')}</div>`;
const filmRows=(target='media-details',selected=false)=>films.map((f,i)=>row(f,`MKV · ${durations[i]} · ${i? '1080p':'4K UHD'}`,target,'video',{image:i,active:selected&&i<2,end:selected?(i<2?'✓':'○'):''})).join('');
const trackRows=(target='audio-player',reorder=false)=>tracks.map((t,i)=>row(`${String(i+1).padStart(2,'0')}  ${t}`,'Mara Ellison · Open Road',target,'audio',{image:i,active:i===2,end:reorder?'⠿':trackTimes[i]})).join('');
const mini=()=>`<button class="mini-player" data-target="audio-player">${img(1,'','Open Road album artwork')}<span><strong>Almost Home</strong><small>Mara Ellison</small></span>${ico('play')}</button>`;
const playerControls=()=>`<div class="player-controls"><div class="seek-line"><span data-elapsed>38:14</span><input aria-label="Playback position" type="range" min="0" max="6138" value="2294"><span>1:42:18</span></div><div class="player-transport"><div>${ib('list','Chapters','chapters')}${btn('CC','subtitle-tracks','text-button')}${btn('1×','playback-speed','text-button')}</div><div>${btn('↶ 10',null,'text-button','rewind')}${ib('play','Play or pause',null,'play')}${btn('10 ↷',null,'text-button','forward')}</div><div>${ib('cast','Cast to device','cast-devices')}${ib('lock','Lock player','locked-player')}${ib('more','Playback options','playback-options')}</div></div></div>`;
const player=(portrait=false,locked=false,gesture)=>`<div class="video-stage ${portrait?'portrait-stage':''}">${img(0,'video-still')}<div class="video-shade"></div><div class="video-title">${ib('back','Back to video library','video-library')}<span><strong>The Long Way Home</strong><small>4K UHD · MKV</small></span>${locked?'':ib('more','Playback options','playback-options')}</div>${locked?`<div class="lock-center">${ib('lock','Unlock player','video-player')}<small>Player locked · tap to unlock</small></div>`:`<button class="center-play icon-button" data-action="play" aria-label="Play or pause">${ico('play')}</button><p class="caption">Some journeys bring you home.</p>${playerControls()}`}${gesture?`<div class="gesture-feedback">${ico(gesture==='brightness'?'sun':'volume')}<strong>${gesture==='brightness'?'72%':'125%'}</strong><span>${gesture==='brightness'?'Brightness':'Audio boost'}</span><div class="gesture-meter"></div></div>`:''}</div>`;
function library(){return `${heading('Your library','6 videos · On this device')}<button class="app-search" data-target="search">${ico('search')}<span>Find something to watch</span></button><div class="resume-label">CONTINUE WATCHING</div><button class="resume" data-target="video-player">${img(0)}<span class="resume-shade"></span><span class="resume-copy"><small>64 MIN LEFT</small><strong>The Long Way Home</strong><span>MKV · 4K UHD</span></span><span class="round-play">${ico('play')}</span><span class="resume-progress"></span></button><div class="shelf-title"><h4>Recently added</h4>${btn('See all','video-list','text-button')}</div><div class="poster-shelf">${films.slice(1,4).map((f,i)=>`<button data-target="media-details">${img(i+1)}<strong>${f}</strong><small>${durations[i+1]}</small></button>`).join('')}</div><p class="quiet-note">Your files. Your cinema.</p>`;}
const preferenceSets={
interface:()=>group('APPEARANCE',setting('Theme','Dark · Premiere','theme')+setting('Language','System default')+toggle('Show section headers','Group the library alphabetically'))+group('LIBRARY',toggle('Folders first','Keep directories above media')+toggle('Show hidden files','Include files beginning with a dot',false)+toggle('Show watched marker','Identify films you have already seen')+setting('History & incognito','History enabled')),
video:()=>group('PLAYBACK',setting('Hardware acceleration','Automatic')+setting('Video orientation','Automatic')+toggle('Fast seek','Seek to the nearest keyframe',false)+setting('App-switch behavior','Continue audio in background'))+group('DISPLAY',setting('Preferred resolution','Best available')+toggle('Match video frame rate','On supported displays',false)+setting('Video controls','Gestures & HUD','video-controls')),
'video-controls':()=>group('GESTURES',toggle('Volume gesture','Swipe on the right')+toggle('Brightness gesture','Swipe on the left')+toggle('Double tap to seek','10 seconds forward or back')+toggle('Hold for fast playback','2× while pressed'))+group('ON-SCREEN CONTROLS',toggle('Show seek buttons','Rewind and forward 10 seconds')+setting('Controls timeout','4 seconds')+toggle('Keep screen on','While playback is paused',false)),
audio:()=>group('PLAYBACK',toggle('Resume playback','Restore the last queue')+setting('Preferred audio language','English')+toggle('Headset detection','Pause when headphones are unplugged')+toggle('Play on headset insertion','Resume automatically',false))+group('SOUND',setting('ReplayGain','Track mode')+setting('ReplayGain preamp','0.0 dB')+toggle('Digital audio passthrough','Use supported external decoders',false)+setting('Audio controls','Artwork & queue','audio-controls')),
'audio-controls':()=>group('NOW PLAYING',toggle('Blurred artwork background','Use the current album cover')+toggle('Show track numbers','Display the album track order')+toggle('Show chapter buttons','For media with chapters')+toggle('Show bookmark buttons','Quickly save listening positions'))+group('QUEUE',toggle('Force shuffle','Always shuffle a new queue',false)+toggle('Show bookmark markers','Along the progress bar')),
subtitles:()=>`<div class="subtitle-preview">${img(0)}<span>Some journeys bring you home.</span></div>`+group('CAPTION STYLE',setting('Preset','Classic')+setting('Font','Sans serif')+setting('Font size','22 sp')+toggle('Bold text','Increase weight',false)+setting('Text color','White')+setting('Background opacity','45%'))+group('LANGUAGE',toggle('Load subtitles automatically','When a matching file is found')+setting('Preferred language','English')),
casting:()=>group('DEVICES',toggle('Enable casting','Discover devices on your network')+setting('Available devices','2 devices found','cast-devices'))+group('PLAYBACK',toggle('Audio only','Cast the audio track',false)+toggle('Audio passthrough','Use receiver decoding',false)+setting('Conversion quality','High')),
remote:()=>group('SERVER',toggle('Enable remote access','Available on the local network',false)+setting('Server status','Not running','remote-status')+setting('Set up remote access','Pair a browser','remote-welcome'))+group('SHARED CONTENT',setting('Media library','Videos & audio','remote-content')+toggle('File browser','Allow file browsing',false)+toggle('Network browser','Allow network browsing',false)+toggle('Playback control','Control current playback')+toggle('Playback history','Share recent activity',false)),
auto:()=>group('INTERFACE',range('Title size',100,50,100)+range('Subtitle size',100,50,100)+setting('Queue information','Below the title')+setting('Queue format','Track number / total'))+group('CONTROLS',toggle('Global audio speed','Use the same speed for all audio',false)+toggle('Show speed buttons','Adjust playback speed in the car',false)+toggle('Show seek buttons','Rewind and fast forward',false)),
advanced:()=>group('NETWORK',setting('Network caching','1,000 ms')+toggle('Prefer SMBv1','For legacy servers',false)+setting('User agent','VLC/3.7.1'))+group('PLAYBACK PERFORMANCE',toggle('Time stretching audio','Preserve pitch when changing speed')+setting('Video output','Automatic')+setting('Audio output','Automatic'))+group('TOOLS',setting('Optional features','Experimental options','optional')+setting('Export database','Save a library backup')+setting('Debug logs','Inspect diagnostic output','debug-logs')),
optional:()=>group('AVAILABLE FEATURES',toggle('Optional features','Review before enabling',false)+setting('Feature information','Read the experimental feature notice','feature-warning'))+`<p class="inset-copy">Some features may change or require a restart. Their availability follows the installed VLC version.</p>`,
parental:()=>group('PROTECTION',setting('PIN code','Set a 4-digit PIN','pin')+toggle('Restrict settings','Require PIN to change preferences',false)+toggle('Safe mode','Restrict access to selected actions',false)),
permissions:()=>group('DEVICE ACCESS',setting('Videos & music','Allowed','media-permission')+setting('Notifications','Allowed','notifications')+setting('External storage','Choose an SD card folder','external-storage')+setting('Display over other apps','Required for pop-up playback','popup-player')),
widgets:()=>group('APPEARANCE',setting('Theme','Follow album artwork')+setting('Widget type','Mini player')+toggle('Light theme','Use a light background',false)+range('Opacity',100)+setting('Background color','Charcoal')+setting('Foreground color','Ivory'))+group('CONTROLS',toggle('Show cover','Display album artwork')+toggle('Show seek buttons','Rewind & fast forward')+setting('Forward delay','10 seconds')+setting('Rewind delay','10 seconds')+toggle('Show configuration button','Open widget settings',false))
};
function renderBody(s){
 switch(s.view){
 case 'library':return library();
 case 'video-list':return heading('All videos','6 videos · Name A–Z',ib('more','Display options','display-options'),'video-library')+filmRows();
 case 'groups':return heading('Collections','Your videos, brought together')+['Weekend cinema','Mountain stories','Short films'].map((n,i)=>`<button class="collection-card" data-target="group-detail">${img(i*2)}<span><strong>${n}</strong><small>${i+2} videos</small></span>${ico('next')}</button>`).join('');
 case 'group':return heading('Mountain stories','2 films · 2 hr 30 min','', 'video-groups')+`<div class="group-banner">${img(1)}<span>Take the long way.</span></div>`+btn('▶ Play all','video-player','button primary')+coverGrid(films.slice(0,2));
 case 'selection':return heading('2 selected','Choose an action below',ib('close','Cancel selection','video-library'))+filmRows('media-details',true)+`<div class="selection-actions">${btn('Add to playlist','add-playlist')}${btn('Group','add-group')}${btn('Delete','delete')}</div>`;
 case 'details':return heading('Media information','','','video-library')+img(0,'detail-art')+`<h4 class="detail-title">The Long Way Home</h4><div class="detail-badges"><span>4K UHD</span><span>MKV</span><span>1:42:18</span></div><div class="detail-stats"><div><small>VIDEO</small><strong>H.265 / HEVC</strong><span>3840 × 2160 · 24 fps</span></div><div><small>AUDIO</small><strong>AAC · 5.1</strong><span>English · 48 kHz</span></div></div><p class="section-label">FILE</p><p class="file-name">the_long_way_home.mkv</p><p class="inset-copy">Internal storage / Movies<br>3.2 GB · Added 7 October</p>`+btn('▶ Play film','video-player','button primary');
 case 'search':return heading('Search','','','video-library')+field('Search your media','home','search')+chips(['All','Videos','Audio','Folders'],'All')+`<p class="section-label">VIDEOS · 1 RESULT</p>`+row(films[0],'4K UHD · 1:42:18','media-details','video',{image:0})+`<p class="section-label">TRACKS · 1 RESULT</p>`+row('Almost Home','Mara Ellison · Open Road','audio-player','audio',{image:1})+`<p class="section-label">FOLDERS · 1 RESULT</p>`+row('Home movies','Internal storage / Videos','folder','folder');
 case 'empty':return heading(s.category==='Video'?'Your library':'Playlists')+`<div class="empty-state"><div class="empty-symbol">${ico(s.category==='Video'?'video':'list')}</div><h4>${s.heading}</h4><p>${s.copy}</p>${btn(s.cta,s.target,'button primary')}</div>`;
 case 'artists':return heading('Your music','18 artists · On this device')+tabsAudio('Artists')+['Mara Ellison','The Northline','Aster Field','June & the Pines'].map((n,i)=>row(n,`${i+2} albums · ${i*9+12} tracks`,'artist-detail','audio',{image:i})).join('')+mini();
 case 'albums':return heading('Your music','24 albums · On this device')+tabsAudio('Albums')+coverGrid(['Open Road','Northbound','Blue Hours','Quiet Places'],'album-detail')+mini();
 case 'tracks':return heading('Your music','128 tracks · On this device')+tabsAudio('Tracks')+`<div class="button-pair">${btn('▶ Play all','audio-player','button primary')}${btn('⇄ Shuffle','audio-player')}</div>`+trackRows()+mini();
 case 'genres':return heading('Your music','Browse by genre')+tabsAudio('Genres')+`<div class="genre-grid">${['Indie folk','Ambient','Alternative','Soundtracks','Electronic','Jazz'].map((n,i)=>`<button data-target="genre-detail" class="genre-card">${img(i)}<span>${n}</span><small>${i+3} albums</small></button>`).join('')}</div>`+mini();
 case 'artist':return heading('Mara Ellison','3 albums · 24 tracks','','audio-artists')+`<div class="artist-hero">${img(1)}<span>Music for the long way home.</span></div>`+btn('▶ Play artist','audio-player','button primary')+`<p class="section-label">ALBUMS</p>`+coverGrid(['Open Road','Northern Lights'],'album-detail')+row('Almost Home','Most played track','audio-player','audio',{image:1});
 case 'album':return heading('Open Road','Mara Ellison · 2024','','audio-albums')+`<div class="album-hero">${img(1)}<div><strong>Open Road</strong><small>6 tracks · 26 minutes</small>${btn('▶ Play album','audio-player','button primary')}</div></div>`+trackRows();
 case 'genre':return heading('Indie folk','6 albums · 42 tracks','','audio-genres')+`<p class="section-label">ALBUMS</p>`+coverGrid(['Open Road','Quiet Places'],'album-detail')+`<p class="section-label">TOP TRACKS</p>`+trackRows().split('</button>').slice(0,2).join('</button>')+'</button>';
 case 'audio-player':return heading('Now playing','Open Road','','audio-tracks')+img(1,'album-art','Open Road album artwork')+`<div class="now-copy"><h4>Almost Home</h4><p>Mara Ellison</p></div>${range('Track position',102,0,242)}<div class="audio-times"><span>1:42</span><span>4:02</span></div><div class="audio-transport">${ib('shuffle','Shuffle',null,'Shuffle')}${ib('back','Previous track',null,'Previous track')}${ib('play','Play or pause',null,'play')}${ib('next','Next track',null,'Next track')}${ib('list','Open queue','audio-queue')}</div><div class="player-shortcuts">${btn('Equalizer','equalizer','text-button')}${btn('Sleep timer','sleep-timer','text-button')}${btn('Bookmarks','audio-bookmarks','text-button')}</div>`;
 case 'queue':return heading('Up next','6 tracks · 26 minutes','','audio-player')+`<div class="queue-current">${img(1)}<div><small>NOW PLAYING</small><strong>Almost Home</strong><span>Mara Ellison</span></div>${ico('audio')}</div><p class="section-label">QUEUE</p>`+trackRows('audio-player',true)+`<div class="button-pair">${btn('Save playlist','create-playlist')}${btn('Clear queue',null,'button','Queue cleared in preview')}</div>`;
 case 'bookmarks':if(s.category==='Audio')return heading('Bookmarks','Open Road · Mara Ellison','','audio-player')+img(1,'detail-art','Open Road album artwork')+row('Verse two','Almost Home · 01:42','audio-player','bookmark')+row('Guitar interlude','Open Road · 02:18','audio-player','bookmark')+row('Final chorus','First Light · 03:04','audio-player','bookmark')+btn('+ Add bookmark',null,'button primary','Audio bookmark added at 01:42');
 return heading('Bookmarks','The Long Way Home','',''+(s.category==='Audio'?'audio-player':'video-player'))+`<div class="bookmark-still">${img(0)}<span>38:14 / 1:42:18</span></div>`+row('The valley opens','00:12:40','video-player','bookmark')+row('Arrival at the coast','00:38:14','video-player','bookmark')+row('The last turn','01:06:28','video-player','bookmark')+btn('+ Add bookmark',null,'button primary','Bookmark added at 38:14');
 case 'browse':return heading('Browse','A place for every file')+group('ON THIS DEVICE',row('Internal storage','42.6 GB free of 128 GB','folder','folder')+row('SD card','21.4 GB free of 64 GB','folder','folder'))+group('NETWORK',row('Local network','Discover servers & shares','network','network')+row('Favorites','2 saved locations','network','bookmark'))+group('QUICK ACCESS',row('Movies','6 videos','folder','video')+row('Music','128 tracks','audio-tracks','audio'));
 case 'folder':case 'share':case 'file-picker':return heading(s.view==='share'?'Cinema server':s.view==='file-picker'?'Choose a file':'Movies',s.view==='share'?'SMB / cinema / films':'Internal storage / Movies','',s.view==='share'?'network':'browse')+`<div class="breadcrumb">${ico('folder')} ${s.view==='share'?'cinema / films':'storage / Movies'}</div>`+row('Short films','Folder · 3 items','folder','folder')+row('Subtitles','Folder · 4 items','file-picker','folder')+filmRows(s.view==='file-picker'?'subtitle-tracks':'media-details').split('</button>').slice(0,3).join('</button>')+'</button>'+row('the_long_way_home.en.srt','Subtitle file · 64 KB','subtitle-tracks','list');
 case 'scan':return heading('Media library folders','Choose folders to scan','','settings')+toggle('Scan all storage','Find video and audio automatically',false)+`<p class="section-label">INTERNAL STORAGE</p>`+toggle('Movies','6 videos')+toggle('Music','128 tracks')+toggle('Downloads','12 media files',false)+toggle('DCIM','Camera recordings',false)+`<p class="section-label">SD CARD</p>`+toggle('Travel films','4 videos')+btn('Scan selected folders',null,'button primary','Scan started · 5 folders');
 case 'network':return heading('Local network','Browse devices on your Wi-Fi','','browse')+group('FAVORITES',row('Cinema server','SMB · cinema.local','network-share','network')+row('Studio archive','FTP · studio.local','network-share','network'))+group('DISCOVERED',row('Living room NAS','SMB · 192.168.1.24','network-share','network'))+btn('+ Add server','connect-server','button primary')+`<p class="quiet-note">Connected to Home Wi-Fi</p>`;
 case 'server':return heading('Connect to server','Add a network location','','network')+chips(['SMB','FTP','SFTP','NFS'],'SMB')+field('Server address','cinema.local')+field('Port','445','number')+field('Shared folder','films')+field('Username','viewer')+field('Password','example','password')+toggle('Save this server','Add to favorites')+btn('Connect','network-share','button primary');
 case 'stream':return heading('Open a stream','Play an address directly','','more')+`<div class="stream-graphic">${ico('network')}</div>`+field('Network address','','url','https://example.com/video.mp4')+btn('Open stream','video-player','button primary')+`<p class="section-label">RECENT STREAMS</p>`+row('Coast live','https://example.com/coast.m3u8','video-player','video')+row('Radio North','https://example.com/radio','audio-player','audio')+btn('View stream history','stream-history','text-button');
 case 'streams':return heading('Streams','Recently opened addresses','','more')+row('Coast live','HLS · Opened today','video-player','video',{image:2})+row('Radio North','Audio · Opened yesterday','audio-player','audio',{image:1})+row('Mountain cinema','MP4 · Opened 6 October','video-player','video',{image:0})+btn('+ Open new stream','stream','button primary');
 case 'playlists':return heading('Your playlists','Collections worth returning to',ib('plus','Create playlist','create-playlist'))+['Weekend cinema','Road trip','Quiet evenings'].map((n,i)=>`<button class="playlist-cover" data-target="playlist-detail">${img(i)}${img(i+1)}<span><strong>${n}</strong><small>${i?12:3} items · ${i?'Audio':'Video'}</small></span>${ico('next')}</button>`).join('')+btn('+ Create playlist','create-playlist','button primary');
 case 'playlist':case 'playlist-edit':return heading('Weekend cinema',s.view==='playlist-edit'?'Reorder this collection · 3 films':'3 films · 3 hr 47 min',ib(s.view==='playlist-edit'?'check':'more',s.view==='playlist-edit'?'Save playlist':'Edit playlist',s.view==='playlist-edit'?'playlist-detail':'playlist-edit'),'playlists')+`<div class="playlist-art">${img(0)}${img(1)}${img(2)}</div><div class="button-pair">${btn('▶ Play all','video-player','button primary')}${btn('⇄ Shuffle','video-player')}</div>`+films.slice(0,3).map((f,i)=>row(f,durations[i],'video-player','video',{image:i,end:s.view==='playlist-edit'?'⠿':''})).join('')+(s.view==='playlist-edit'?btn('+ Add media','add-playlist'):'');
 case 'player':return player();
 case 'portrait-player':return player(true);
 case 'locked':return player(false,true);
 case 'gesture':return player(false,false,s.gesture);
 case 'popup':return heading('Your library','6 videos · On this device')+filmRows()+`<div class="floating-player">${img(0)}<span>${ib('close','Close pop-up',null,'Close pop-up')}${ib('play','Play or pause',null,'play')}${ib('video','Expand player','video-player')}</span></div>`;
 case 'equalizer':return heading('Equalizer','Shape the sound','','audio-player')+toggle('Enable equalizer','Apply to current playback')+`<div class="equalizer-preset">${btn('Cinema ▾','equalizer-presets')}${btn('Save preset','equalizer-presets','text-button')}</div>${range('Preamp',0,-20,20)}<div class="eq-bands">${['60','170','310','600','1K','3K','6K','12K'].map((f,i)=>`<label><input type="range" aria-label="${f} Hz equalizer" min="-20" max="20" value="${[5,3,0,-2,1,4,3,2][i]}"><span>${f}</span></label>`).join('')}</div><div class="eq-scale"><span>−20 dB</span><span>0 dB</span><span>+20 dB</span></div>`+btn('Reset bands',null,'button','Equalizer reset')+`<p class="inset-copy">A little presence. A little warmth.<br>Your sound, your choice.</p>`;
 case 'info':return heading('Playback information','The Long Way Home','','video-player')+img(0,'detail-art')+group('VIDEO',setting('Codec','H.265 / HEVC')+setting('Resolution','3840 × 2160')+setting('Frame rate','24 fps')+setting('Decoder','Hardware accelerated'))+group('AUDIO',setting('Codec','AAC · 5.1 channels')+setting('Sample rate','48,000 Hz'))+`<div class="stats-graph"><span></span><small>Playback frames · Stable</small></div>`;
 case 'sheet':return renderSheet(s);
 case 'more':return heading('More','Everything else, close at hand')+`<div class="more-tiles">${btn(ico('settings')+'Settings','settings')}${btn('<span class="vlc-mark">▲</span>About VLC','about')}</div>`+group('YOUR MEDIA',row('Playback history','Pick up where you left off','history','video')+row('Streams','Open a network address','stream','network')+row('Bookmarks','Saved moments','bookmarks','bookmark'))+group('TOOLS',row('Equalizer','Find your sound','equalizer','audio')+row('Remote access','Connect a browser','remote-settings','network'));
 case 'history':return heading('History','Recently played','','more')+`<p class="section-label">TODAY</p>`+row(films[0],'Resume at 38:14','video-player','video',{image:0})+row('Almost Home','Mara Ellison · Completed','audio-player','audio',{image:1})+`<p class="section-label">YESTERDAY</p>`+row(films[2],'Resume at 12:02','video-player','video',{image:2})+row(films[1],'Completed','video-player','video',{image:1})+btn('Clear history',null,'text-button','History cleared in preview');
 case 'settings':return heading('Settings','Make VLC yours',ib('search','Search settings','settings-search'),'more')+group('MEDIA LIBRARY',setting('Folders','Choose what VLC scans','scan-folders')+toggle('Auto rescan','Refresh when opening VLC'))+group('PERSONALIZE',setting('Interface','Theme, language & library','interface-settings')+setting('Video','Playback & controls','video-settings')+setting('Audio','Sound & headset behavior','audio-settings')+setting('Subtitles','Appearance & language','subtitle-settings'))+group('MORE',setting('Casting','Devices & conversion','casting-settings')+setting('Remote access','Pair a browser','remote-settings')+setting('Parental controls','PIN & restrictions','parental')+setting('Android Auto','Interface & player controls','android-auto')+setting('Widgets','Appearance & controls','widgets')+setting('Permissions','Review device access','permissions')+setting('Equalizer presets','Saved sound profiles','equalizer-presets')+setting('Advanced','Network & data tools','advanced'));
 case 'preferences':return heading(s.title,'VLC preferences','','settings')+preferenceSets[s.section]();
 case 'settings-search':return heading('Search settings','','','settings')+field('Search settings','subtitles','search')+`<p class="section-label">5 RESULTS</p>`+row('Subtitle appearance','Settings / Subtitles','subtitle-settings','settings')+row('Preferred subtitle language','Settings / Subtitles','subtitle-settings','settings')+row('Subtitle encoding','Settings / Subtitles','subtitle-settings','settings')+row('Load subtitles automatically','Settings / Subtitles','subtitle-settings','settings')+row('Subtitle delay','Playback / Synchronization','sync','settings');
 case 'presets':return heading('Equalizer presets','Keep the sound you like','','equalizer')+['Flat','Cinema','Acoustic','Bass boost','Headphones','My evening mix'].map((p,i)=>choice(p,i===1?'Current preset':'',i===1)).join('')+btn('+ Save current preset',null,'button primary','Preset saved in preview');
 case 'pin':return heading('Create your PIN','Protect settings and restricted actions','','parental')+`<div class="pin-view">${ico('lock')}<h4>Choose a 4-digit PIN</h4><div class="pin-dots"><span></span><span></span><span></span><span></span></div><div class="keypad">${['1','2','3','4','5','6','7','8','9','Clear','0','⌫'].map(n=>btn(n,null,'key','pin:'+n)).join('')}</div></div>`;
 case 'about':return heading('About VLC','','','more')+`<div class="about-brand"><span class="big-cone">▲</span><h4>VLC</h4><p>Media player, for everyone.</p><small>Version 3.7.1 · Android</small></div>`+group('THE PROJECT',row('VideoLAN','A worldwide open source community',null,'network')+row('Contributors','The people behind VLC','authors','audio')+row('Open source licenses','Libraries & acknowledgments','licenses','list')+row('Feedback & support','Share your experience','feedback','more'))+`<p class="quiet-note">Free software. No ads. Your media.</p>`;
 case 'licenses':return heading('Open source licenses','Built by a community','','about')+['LibVLC','FFmpeg','dav1d','Kotlin','AndroidX','Material Components'].map((l,i)=>row(l,['GPL / LGPL','LGPL / GPL','BSD-2-Clause','Apache-2.0','Apache-2.0','Apache-2.0'][i],'license-detail','list')).join('');
 case 'authors':return heading('Contributors','People make VLC possible','','about')+`<div class="community-art">${Array.from({length:12},(_,i)=>`<span>${['VL','FF','DV','UX','QA','OS'][i%6]}</span>`).join('')}</div><h4 class="detail-title">Made around the world.</h4><p class="inset-copy">Developers, designers, translators, testers, and everyone who helps make free media software possible.</p>`+group('CONTRIBUTIONS',row('Development','Playback, library & Android',null,'settings')+row('Translations','VLC in your language',null,'list')+row('Testing & support','Making every release better',null,'check'));
 case 'feedback':return heading('Feedback','Help improve VLC','','about')+`<div class="support-art">${ico('headphones')}</div><h4 class="detail-title">How can we help?</h4><p class="inset-copy">Tell us what happened and include diagnostic information when useful.</p>`+row('Report an issue','Describe a problem',null,'more')+row('Capture debug logs','Include playback diagnostics','debug-logs','list')+row('Get help','Find documentation & community support',null,'network')+row('Share app information','VLC 3.7.1 · Android',null,'video');
 case 'logs':return heading('Debug logs','Diagnostic capture','','advanced')+`<div class="log-status"><span class="status-dot"></span> Ready to capture</div><div class="log-window"><p>17:42:10  VLC media library ready</p><p>17:42:11  Input: MKV container</p><p>17:42:11  Video: HEVC 3840×2160</p><p>17:42:11  Audio: AAC 5.1</p><p>17:42:12  Decoder initialized</p><p>17:42:12  Playback started</p></div><div class="button-pair">${btn('Start recording',null,'button primary','Diagnostic recording started')}${btn('Export logs',null,'button','Log export preview')}</div><p class="inset-copy">Illustrative diagnostics. No device data is collected by this proposal.</p>`;
 case 'onboarding':return onboarding(s.step);
 case 'remote-onboarding':return remoteOnboarding(s.step);
 case 'otp':return heading('Pair a browser','One-time authentication','','remote-settings')+`<div class="pair-symbol">${ico('lock')}</div><h4 class="detail-title">Enter this code in your browser</h4><div class="otp-code">482 196</div><p class="inset-copy centered">Illustrative code · Expires in 02:00<br>Only share with a browser you want to connect.</p>`+btn('Cancel pairing','remote-settings','button')+btn('Show connected state','remote-status','text-button');
 case 'remote-status':return heading('Remote access','Server status','','remote-settings')+`<div class="server-status"><span class="status-dot"></span><strong>Ready on your network</strong><small>Illustrative connection state</small></div>`+field('Browser address','https://192.168.1.24:8080')+btn('Pair a browser','remote-code','button primary')+group('PAIRED DEVICES',row('Living room browser','Connected · Playback control',null,'network',{end:'●'}))+group('SHARED CONTENT',setting('Media library','Videos & audio','remote-content')+toggle('Playback controls','Allow remote play and pause'))+btn('Stop server',null,'text-button','Server stopped in preview');
 default:return '';
 }
}
function onboarding(step){
 const config={welcome:['Your media. Your world.','Films, music, and everything in between. All the files you love, beautifully in one place.','Get started','theme'],theme:['Set the mood.','Choose an appearance that feels right. You can change it in Settings.','Continue','media-permission'],media:['Make room for your library.','Let VLC find videos and music on your device. You choose which folders to scan.','Allow media access','first-scan'],scan:['Find your favorites.','Scan your media automatically, or choose the folders you want in your library.','Continue','notifications'],notifications:['Keep the controls close.','Playback notifications let you pause, skip, and return to your media from the lock screen.','Allow notifications','video-library'],'no-access':['Start with a single file.','You can still open a file or network stream. Media access can be granted whenever you are ready.','Open a file','file-picker']};
 const [title,copy,label,target]=config[step];
 let content='';
 if(step==='theme')content=`<div class="theme-preview"><button class="theme-tile chosen" data-choice aria-pressed="true"><div class="theme-mini dark"><i></i><span></span><b></b></div>Dark</button><button class="theme-tile" data-choice aria-pressed="false"><div class="theme-mini light"><i></i><span></span><b></b></div>Light</button></div>${choice('Follow system','Switch with Android appearance',false)}`;
 else if(step==='scan')content=choice('Scan automatically','Find all video and audio files',true)+choice('Choose folders','Select specific locations',false)+btn('Choose folders','scan-folders','text-button');
 else if(step==='media')content=`<div class="access-cards"><span>${ico('video')}<strong>Videos</strong><small>Your local films</small></span><span>${ico('audio')}<strong>Audio</strong><small>Music & recordings</small></span></div>`;
 else if(step==='notifications')content=`<div class="notification-preview"><span class="vlc-mark">▲</span><div><strong>Almost Home</strong><small>Mara Ellison</small><span>‹　Ⅱ　›</span></div>${img(1)}</div>`;
 else if(step==='no-access')content=btn('Open a stream','stream','button');
 else content=`<div class="welcome-mosaic">${img(0)}${img(1)}${img(2)}</div>`;
 return `<div class="onboarding-top"><span class="vlc-mark">▲</span><span>VLC · PREMIERE</span>${btn('Skip','video-library','text-button')}</div><div class="onboarding-content"><h3>${title}</h3><p>${copy}</p>${content}</div><div class="onboarding-bottom"><div class="step-dots">${[0,1,2,3,4].map((i)=>`<i class="${i===Object.keys(config).indexOf(step)?'active':''}"></i>`).join('')}</div>${btn(label,target,'button primary')}${step==='media'||step==='notifications'?btn('Not now',step==='media'?'no-permission':'video-library','text-button'):''}</div>`;
}
function remoteOnboarding(step){
 const config={welcome:['VLC, from your browser.','Browse your library and control playback from another device on the same network.','remote-control'],control:['A little more freedom.','Play, pause, browse, and transfer media from a connected browser.','remote-content'],content:['You choose what to share.','Keep control over the media and actions available remotely.','remote-encryption'],encryption:['A private connection.','Remote access uses an encrypted connection to protect your media on the network.','remote-auth'],auth:['Pair with a one-time code.','Enter the code shown on your phone in the browser you want to connect.','remote-code']};
 const [title,copy,next]=config[step];
 return heading('Remote access','Connect a trusted browser','','remote-settings')+`<div class="remote-illustration"><span>${ico('video')}</span><i></i><span>${ico(step==='encryption'||step==='auth'?'lock':'network')}</span></div><h4 class="detail-title">${title}</h4><p class="inset-copy">${copy}</p>`+(step==='content'?toggle('Videos','Share your video library')+toggle('Audio','Share your music collection')+toggle('Playback control','Allow play, pause, and seeking')+toggle('File browsing','Access folders directly',false):`<div class="remote-feature">${ico(step==='auth'?'lock':'check')}<span>${step==='auth'?'One code. One trusted connection.':step==='encryption'?'Encrypted access on your local network.':'Your library stays on your device.'}</span></div>`)+`<div class="onboarding-bottom">${btn(step==='auth'?'Show pairing code':'Continue',next,'button primary')}</div>`;
}
function sheetContent(key){
 switch(key){
 case 'options':return `<div class="option-grid">${[['Playback speed','playback-speed','play'],['Sleep timer','sleep-timer','lock'],['Equalizer','equalizer','audio'],['Audio delay','sync','audio'],['Audio tracks','audio-track-picker','audio'],['Subtitles','subtitle-tracks','list'],['Jump to time','jump-time','next'],['Chapters','chapters','list'],['Bookmarks','bookmarks','bookmark'],['A–B repeat','ab-repeat','video'],['Video size','video-size','video'],['Pop-up player','popup-player','video'],['Information','playback-info','settings']].map(([t,d,i])=>btn(ico(i)+`<span>${t}</span>`,d)).join('')}</div>`;
 case 'audio-tracks':return choice('English · AAC 5.1','Track 1 · Original',true)+choice('French · AAC stereo','Track 2 · Dubbed')+choice('Audio description','Track 3 · English')+btn('Adjust audio delay','sync','text-button');
 case 'subtitles':return choice('English','Track 1 · SRT',true)+choice('French','Track 2 · SRT')+choice('Off','Hide subtitles')+`<div class="sheet-divider"></div>`+row('Choose subtitle file','Open an SRT or ASS file','file-picker','folder')+row('Download subtitles','Search by title & language','subtitle-download','download')+row('Subtitle appearance','Font, size & background','subtitle-settings','settings');
 case 'subtitle-search':return field('Film title','The Long Way Home')+field('Year','2024','number')+chips(['English','French','Spanish'],'English')+btn('Find subtitles','subtitle-results','button primary');
 case 'subtitle-results':return `<p class="sheet-copy">English · 3 matches</p>`+['The.Long.Way.Home.2024.2160p','The.Long.Way.Home.WEB-DL','The.Long.Way.Home.BluRay'].map((n,i)=>row(n,`English · SRT · ${i===0?'4K UHD':'1080p'}`,null,'download',{end:'↓'})).join('')+btn('Change search','subtitle-download','text-button');
 case 'speed':return `<div class="big-value">1.00<span>×</span></div>`+range('Playback speed',1,.25,4,.05)+chips(['0.5×','0.75×','1×','1.25×','1.5×','2×'],'1×')+toggle('Preserve pitch','Keep voices sounding natural')+btn('Apply speed','video-player','button primary');
 case 'sync':return `<p class="sheet-copy">Positive values delay the track. Negative values play it earlier.</p><div class="delay-control"><strong>Audio delay</strong><div>${btn('−',null,'stepper','delay:-') }<output>0 ms</output>${btn('+',null,'stepper','delay:+')}</div></div><div class="delay-control"><strong>Subtitle delay</strong><div>${btn('−',null,'stepper','delay:-')}<output>0 ms</output>${btn('+',null,'stepper','delay:+')}</div></div>`+btn('Reset timing',null,'button','Reset timing');
 case 'jump':return `<p class="sheet-copy">Jump directly to a position in this film.</p>`+field('Hours : minutes : seconds','00:38:14')+`<p class="quiet-note">Duration 01:42:18</p>`+btn('Jump to time','video-player','button primary');
 case 'chapters':return ['Opening','Through the mountains','Arrival at the coast','The long way home'].map((n,i)=>row(`${i+1}. ${n}`,['00:00:00','00:12:40','00:38:14','01:06:28'][i],'video-player','list',{active:i===2})).join('');
 case 'sleep':return `<div class="big-value">30<span>min</span></div>`+chips(['15 min','30 min','45 min','60 min'],'30 min')+field('Custom duration','30','number')+toggle('Finish current track','Stop at the end of the playing track',false)+btn('Start timer',null,'button primary','Sleep timer set for 30 minutes');
 case 'cast':return `<p class="sheet-copy">Choose a device on your local network.</p>`+row('Living room TV','Ready to connect',null,'cast',{end:'Connect'})+row('Kitchen speaker','Audio only',null,'audio',{end:'Connect'})+`<p class="quiet-note">Searching for nearby devices…</p>`+btn('Casting settings','casting-settings','text-button');
 case 'repeat':return `<p class="sheet-copy">Repeat a section of the current film.</p><div class="repeat-markers"><span><small>START · A</small><strong>00:38:14</strong></span><span><small>END · B</small><strong>00:40:28</strong></span></div>`+range('Repeat segment',38,0,102)+btn('Repeat this section',null,'button primary','A–B repeat enabled')+btn('Clear markers',null,'text-button','Repeat markers cleared');
 case 'size':return ['Best fit','Fit screen','Fill screen','16:9','4:3','Original size'].map((n,i)=>choice(n,['Keep the whole picture','Use available space','Crop to fill the display','','','Use source dimensions'][i],!i)).join('');
 case 'media-actions':return `<div class="sheet-media">${img(0)}<span><strong>${films[0]}</strong><small>MKV · 4K UHD · 1:42:18</small></span></div>`+row('Play from beginning','','video-player','play')+row('Play next','Add after current item',null,'list')+row('Add to playlist','','add-playlist','plus')+row('Media information','','media-details','video')+row('Rename','','rename','more')+row('Delete file','','delete','close');
 case 'display':return `<p class="section-label">VIEW</p>`+chips(['Grid','List'],'Grid')+`<p class="section-label">SORT BY</p>`+['Name','Duration','Date added','Last modified'].map((n,i)=>choice(n,'',!i)).join('')+toggle('Descending order','Reverse the sort direction',false)+btn('Apply display','video-list','button primary');
 case 'add-playlist':return `<p class="sheet-copy">Add 2 selected videos to a collection.</p>`+choice('Weekend cinema','3 films',true)+choice('Road trip','12 tracks')+choice('Quiet evenings','8 tracks')+btn('+ Create a new playlist','create-playlist','text-button')+btn('Add selected media',null,'button primary','2 videos added to Weekend cinema');
 case 'create-playlist':return `<p class="sheet-copy">Give this collection a name.</p>`+field('Playlist name','Weekend cinema')+toggle('Include current queue','3 films · 3 hr 47 min')+btn('Save playlist','playlists','button primary');
 case 'group':return `<p class="sheet-copy">Group related videos together.</p>`+choice('Mountain stories','2 films',true)+choice('Short films','3 films')+field('Or create a new group','','text','Collection name')+btn('Add to group','video-groups','button primary');
 case 'rename':return field('File name','the_long_way_home')+`<p class="sheet-copy">The .mkv extension will be kept.</p><div class="button-pair">${btn('Cancel','video-library')}${btn('Save name',null,'button primary','File renamed in preview')}</div>`;
 case 'delete':return `<div class="destructive-icon">${ico('close')}</div><p class="sheet-copy">Delete <strong>the_long_way_home.mkv</strong> from this device? This file will be permanently removed.</p><div class="button-pair">${btn('Keep file','video-library')}${btn('Delete file',null,'button danger','Delete action preview · no file removed')}</div>`;
 case 'duplicate':return `<p class="sheet-copy">2 items are already in Weekend cinema. Would you like to add them again?</p>`+row(films[0],durations[0],'media-details','video',{image:0})+row(films[1],durations[1],'media-details','video',{image:1})+`<div class="button-pair">${btn('Skip duplicates',null,'button primary','Duplicates skipped')}${btn('Add anyway',null,'button','Duplicate items added in preview')}</div>`;
 case 'login':return `<p class="sheet-copy">Sign in to Cinema server<br><strong>smb://cinema.local/films</strong></p>`+field('Username','viewer')+field('Password','','password')+toggle('Remember sign-in','For this server only',false)+btn('Connect','network-share','button primary');
 case 'error':return `<div class="error-mark">!</div><p class="sheet-copy">Cinema server could not be reached. Check that the device is on the same network and the server is available.</p><div class="button-pair">${btn('Try again','progress','button primary')}${btn('Edit server','connect-server')}</div>`;
 case 'storage':return `<div class="support-art">${ico('folder')}</div><p class="sheet-copy">To save or change files on this SD card, choose its folder in the Android storage picker.</p>`+btn('Choose SD card folder','file-picker','button primary')+btn('Not now','browse','text-button');
 case 'notification':return `<p class="sheet-copy">Allow playback notifications to keep audio controls available while VLC is in the background.</p>`+toggle('Remind me later','Show this reminder again',false)+btn('Continue to permission step','notifications','button primary')+btn('Not now','audio-player','text-button');
 case 'replace':return `<p class="sheet-copy">There are 6 tracks in your current queue. What would you like to do with this album?</p>`+row('Play next','Keep the current queue',null,'next')+row('Append to queue','Play after the existing tracks',null,'plus')+row('Replace queue','Start this album instead','audio-player','play');
 case 'resume':return `<div class="sheet-media">${img(0)}<span><strong>${films[0]}</strong><small>Last position 38:14</small></span></div>`+btn('Resume at 38:14','video-player','button primary')+btn('Start from beginning','video-player','button')+toggle('Always resume','Remember this preference',false);
 case 'whats-new':return `<p class="sheet-copy">A refreshed way to enjoy your media.</p>`+row('A library that feels like home','Resume and explore your files','video-library','video')+row('Clearer playback tools','Tracks, speed & timing together','playback-options','play')+row('Remote access','Connect a trusted browser','remote-welcome','network')+btn('Explore VLC','video-library','button primary');
 case 'license':return `<p class="section-label">LIBVLC · GPL / LGPL</p><div class="license-text"><p>VLC is free software. You can redistribute it and modify it under the terms of its applicable open source licenses.</p><p>This screen provides a reading surface for the complete license text, copyright notices, and library attribution.</p><p>Visual proposal: the full legal text remains supplied by the native VLC app.</p></div>`+btn('Back to licenses','licenses','button primary');
 case 'feature':return `<p class="sheet-copy">This optional feature is experimental. Its behavior may change, and enabling it may require VLC to restart.</p>`+toggle('Enable optional feature','For this visual preview only',false)+btn('Return to optional features','optional','button primary');
 case 'progress':return `<div class="progress-ring"></div><p class="sheet-copy centered">Connecting to Cinema server…<br><small>Checking available shares</small></p>`+btn('Cancel','network','button')+btn('Preview connected state','network-share','text-button');
 default:return '';
 }
}
function renderSheet(s){
 let underlying;
 if(s.base==='player') underlying=player(true);
 else if(s.base==='audio-player')underlying=renderBody({view:'audio-player'});
 else if(s.base==='network')underlying=renderBody({view:'network'});
 else if(s.base==='browse')underlying=renderBody({view:'browse'});
 else if(s.base==='about')underlying=renderBody({view:'about'});
 else if(s.base==='settings')underlying=renderBody({view:'settings'});
 else if(s.base==='playlist')underlying=renderBody({view:'playlists'});
 else underlying=library();
 return `<div class="sheet-underlay" aria-hidden="true" inert>${underlying}</div><div class="sheet-scrim"></div><div class="bottom-sheet"><div class="sheet-handle"></div><div class="sheet-heading"><h3>${s.title}</h3>${ib('close','Close '+s.title,s.base==='player'?'video-player':s.base==='audio-player'?'audio-player':s.base==='network'?'network':s.base==='playlist'?'playlists':'video-library')}</div><div class="sheet-content">${sheetContent(s.sheet)}</div></div>`;
}
const gallery=document.querySelector('#gallery'),search=document.querySelector('#screen-search'),categories=document.querySelector('#categories');
let active='All screens',focus=null;
const overview=['video-library','audio-player','browse','playlists','portrait-player','settings'];
function card(s){const index=screens.indexOf(s)+1;const activeNav=s.category==='Video'?'Video':s.category==='Audio'?'Audio':s.category==='Browse'?'Browse':s.category==='Playlists'?'Playlists':'More';const noNav=['Playback','First run','Remote pairing','Dialogs'].includes(s.category)||['audio-player','audio-queue','pin','equalizer','audio-bookmarks'].includes(s.id);return `<article class="screen-card ${s.landscape?'wide':''}" data-id="${s.id}" data-title="${esc(s.title)}"><div class="screen-label"><span>${String(index).padStart(2,'0')} / ${s.type}</span><button data-focus="${s.id}" aria-label="Open ${esc(s.title)}">${s.title}<span aria-hidden="true">↗</span></button></div><div class="phone ${s.landscape?'landscape':''} ${s.view==='sheet'?'sheet-phone':''} ${['player','portrait-player','locked','gesture'].includes(s.view)?'player-phone':''}">${s.landscape?'':`<div class="statusbar"><span>9:41</span><span>▂▅▇ &nbsp; ◉ &nbsp; ▰</span></div>`}<div class="app-body">${renderBody(s)}</div>${noNav?'':nav(activeNav)}${s.landscape?'':'<div class="home-indicator"><span></span></div>'}</div><div class="screen-note"><p>${s.description}</p><button data-focus="${s.id}">Explore screen ${ico('next')}</button></div></article>`;}
gallery.innerHTML=order.map((c,i)=>`<section class="category-section" data-category="${c}"><div class="category-heading"><span>${String(i+1).padStart(2,'0')}</span><h2>${c}</h2><small>${screens.filter(s=>s.category===c).length} screens & states</small></div><div class="screen-grid">${screens.filter(s=>s.category===c).map(card).join('')}</div></section>`).join('');
categories.innerHTML=['All screens',...order].map((c)=>`<button data-category="${c}" aria-pressed="${c===active}">${c}<small>${c==='All screens'?screens.length:screens.filter(s=>s.category===c).length}</small></button>`).join('');
document.querySelector('#total').textContent=screens.length;
function matched(){const q=search.value.trim().toLowerCase();return screens.filter(s=>(active==='All screens'||s.category===active)&&(!q||`${s.title} ${s.category} ${s.description}`.toLowerCase().includes(q)));}
function update(){const results=matched(),ids=new Set(focus?[focus]:results.map(s=>s.id));gallery.querySelectorAll('.screen-card').forEach(el=>el.hidden=!ids.has(el.dataset.id));gallery.querySelectorAll('.category-section').forEach(el=>el.hidden=![...el.querySelectorAll('.screen-card')].some(card=>!card.hidden));document.body.classList.toggle('focus-mode',!!focus);document.querySelector('#focus-controls').hidden=!focus;document.querySelector('#empty-results').hidden=ids.size>0;categories.querySelectorAll('button').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.category===active)));document.querySelector('#result-count').textContent=focus?'1 screen in focus':`${results.length} of ${screens.length} screens`;document.querySelector('#save-board').textContent=focus?'Save screen image':active==='All screens'&&!search.value?'Save overview image':'Save view image';if(focus)document.querySelector('#focus-title').textContent=screens.find(s=>s.id===focus).title;document.querySelector('#download-board').hidden=true;}
function setFocus(id,scroll=true){if(!screens.some(s=>s.id===id))return;focus=id;history.replaceState(null,'','#'+id);update();if(scroll)document.querySelector('#focus-controls').scrollIntoView({block:'start',behavior:'instant'});}
function exitFocus(){focus=null;history.replaceState(null,'',location.pathname+location.search);update();}
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),2800);}
search.addEventListener('input',()=>{focus=null;history.replaceState(null,'',location.pathname);update();});
categories.addEventListener('click',e=>{const b=e.target.closest('[data-category]');if(!b)return;active=b.dataset.category;focus=null;search.value='';history.replaceState(null,'',location.pathname);update();});
document.querySelector('#exit-focus').addEventListener('click',exitFocus);
for(const [id,delta] of [['previous',-1],['next',1]])document.querySelector('#'+id).addEventListener('click',()=>{const list=matched();const current=list.findIndex(s=>s.id===focus);const use=list.length&&current>=0?list:screens;const n=use.findIndex(s=>s.id===focus);setFocus(use[(n+delta+use.length)%use.length].id,false);});
document.addEventListener('click',e=>{
 const focusButton=e.target.closest('[data-focus]');if(focusButton){setFocus(focusButton.dataset.focus);return;}
 const target=e.target.closest('[data-target]');if(target){setFocus(target.dataset.target);return;}
 const toggleButton=e.target.closest('[data-toggle]');if(toggleButton){toggleButton.setAttribute('aria-checked',String(toggleButton.getAttribute('aria-checked')!=='true'));return;}
 const choiceButton=e.target.closest('[data-choice]');if(choiceButton){const parent=choiceButton.closest('.chips,.theme-preview')||choiceButton.parentElement;parent.querySelectorAll('[data-choice]').forEach(b=>b.setAttribute('aria-pressed',String(b===choiceButton)));return;}
 const action=e.target.closest('[data-action]');if(!action)return;const key=action.dataset.action;
 if(key==='play'){const playing=action.getAttribute('aria-pressed')!=='true';const phone=action.closest('.phone');phone.querySelectorAll('[data-action="play"]').forEach(b=>{b.setAttribute('aria-pressed',String(playing));b.innerHTML=ico(playing?'pause':'play');});return;}
 if(key==='rewind'||key==='forward'){const phone=action.closest('.phone'),seek=phone.querySelector('[aria-label="Playback position"]');if(seek){seek.value=Math.max(0,Math.min(6138,Number(seek.value)+(key==='forward'?10:-10)));seek.dispatchEvent(new Event('input',{bubbles:true}));}return;}
 if(key.startsWith('delay:')){const out=action.parentElement.querySelector('output');out.textContent=(parseInt(out.textContent)+(key.endsWith('+')?50:-50))+' ms';return;}
 if(key==='Reset timing'){action.closest('.sheet-content').querySelectorAll('.delay-control output').forEach(o=>o.textContent='0 ms');return;}
 if(key.startsWith('pin:')){const dots=action.closest('.pin-view').querySelectorAll('.pin-dots span'),count=[...dots].filter(d=>d.classList.contains('filled')).length;const v=key.slice(4);if(v==='Clear'){dots.forEach(d=>d.classList.remove('filled'));return;}if(v==='⌫'){if(count)dots[count-1].classList.remove('filled');return;}if(count<4)dots[count].classList.add('filled');if(count===3)toast('PIN entered in preview · no device PIN changed');return;}
 if(key==='Equalizer reset'){action.closest('.phone').querySelectorAll('input[type="range"]').forEach(r=>{r.value=0;r.dispatchEvent(new Event('input',{bubbles:true}));});return;}
 toast(key+' · simulated preview');
});
document.addEventListener('input',e=>{if(e.target.type!=='range')return;const input=e.target,label=input.closest('label');if(label?.querySelector('output'))label.querySelector('output').textContent=input.value;if(input.getAttribute('aria-label')==='Playback position'){const sec=Number(input.value),m=Math.floor(sec/60),s=sec%60;input.closest('.seek-line').querySelector('[data-elapsed]').textContent=`${m}:${String(s).padStart(2,'0')}`;}if(input.getAttribute('aria-label')==='Playback speed'){input.closest('.sheet-content').querySelector('.big-value').innerHTML=Number(input.value).toFixed(2)+'<span>×</span>';}});
window.addEventListener('hashchange',()=>{const id=location.hash.slice(1);if(id)setFocus(id);else exitFocus();});
if(screens.some(s=>s.id===location.hash.slice(1)))focus=location.hash.slice(1);
update();
let exportUrl=null;
document.querySelector('#save-board').addEventListener('click',async()=>{
 const button=document.querySelector('#save-board'),old=button.textContent;button.disabled=true;button.textContent='Preparing image…';
 try{
  const all=matched();let ids=focus?[focus]:active==='All screens'&&!search.value?overview:all.slice(0,12).map(s=>s.id);
  if(!ids.length)throw new Error('Choose a screen first');
  const wrapper=document.createElement('div');wrapper.className='export-root';wrapper.innerHTML=`<div class="export-heading"><p>VLC / PREMIERE</p><h1>${focus?screens.find(s=>s.id===focus).title:active==='All screens'&&!search.value?'One cinematic language. Every corner of VLC.':active}</h1><span>${focus?'Screen design':active==='All screens'&&!search.value?`6-screen overview · ${screens.length} screens in the interactive gallery`:`${ids.length} of ${all.length} screens in this view`}</span></div><div class="export-grid"></div>`;
  const grid=wrapper.querySelector('.export-grid');for(const id of ids){const clone=gallery.querySelector(`[data-id="${id}"]`).cloneNode(true);clone.hidden=false;clone.classList.remove('wide');grid.append(clone);}
  for(const image of wrapper.querySelectorAll('img')){const blob=await(await fetch(image.src)).blob();image.src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob);});image.removeAttribute('loading');}
  /* Mirror current state into serialization: form properties are not attributes. */
  for(const id of ids){const original=gallery.querySelector(`[data-id="${id}"]`),clone=wrapper.querySelector(`[data-id="${id}"]`);[...original.querySelectorAll('input')].forEach((input,i)=>clone.querySelectorAll('input')[i].setAttribute('value',input.value));}
  const css=await(await fetch('styles.css')).text();const width=1260,rows=Math.ceil(ids.length/3),height=210+rows*850;
  const markup=`<div xmlns="http://www.w3.org/1999/xhtml"><style>${css.replace(/(?<![-\w.])body\b/g,'.export-root')}</style>${new XMLSerializer().serializeToString(wrapper)}</div>`;
  const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="${width}" height="${height}"><foreignObject width="100%" height="100%">${markup}</foreignObject></svg>`;
  const picture=new Image();await new Promise((resolve,reject)=>{picture.onload=resolve;picture.onerror=reject;picture.src='data:image/svg+xml;charset=utf-8,'+encodeURIComponent(svg);});
  const canvas=document.createElement('canvas');canvas.width=width*2;canvas.height=height*2;canvas.getContext('2d').drawImage(picture,0,0,canvas.width,canvas.height);
  const blob=await new Promise((resolve,reject)=>canvas.toBlob(b=>b?resolve(b):reject(new Error('Image export failed')),'image/png'));
  if(exportUrl)URL.revokeObjectURL(exportUrl);exportUrl=URL.createObjectURL(blob);const link=document.querySelector('#download-board');link.href=exportUrl;link.download=`vlc-premiere-${active==='All screens'&&!search.value?'overview':active.toLowerCase().replace(/[^a-z]+/g,'-')}.png`;if(focus)link.download=`vlc-premiere-${focus}.png`;link.hidden=false;button.textContent='Image ready';
 }catch(error){toast('Image export failed: '+error.message);button.textContent=old;}finally{button.disabled=false;}
});
})();
